    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float3 iMouse = float3(0.5, 0.5, 0.5);
        float iTime = (amzp_autop>0.5)? amzp_PROGRESS + sin((time*amzp_SPEED)) : amzp_PROGRESS;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((180.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
             float2 uv = satriyaid;
             float completion = iTime;
             float steps = amzp_STEPS;
             float toothHeight = amzp_HEIGHT;
             bool isInterlocking = (amzp_INTLOCK>0.5);
             int shapeType = int(int(amzp_JMODE));
             float offsetXTop = amzp_JTOP.x;
             float offsetYTop = amzp_JTOP.y;
             float offsetXBottom = amzp_JBOT.x;
             float offsetYBottom = amzp_JBOT.y;
             float4 baseColor = amzp_color2;
             float4 jawColor = amzp_color1;
             float jawHeight = completion * 1.0;
             float topBoundary = 1.0 - jawHeight + offsetYTop;
             float bottomBoundary = -1.0 + jawHeight + offsetYBottom;
             bool isJaw = false;
             float uvXTop = uv.x - offsetXTop;
             float uvXBottom = uv.x - offsetXBottom;
             if (steps == 0.0) {
                 if (uv.y > topBoundary || uv.y < bottomBoundary) {
                     isJaw = true;
                 }
             }
             else {
                 float yOffsetTop = 0.0;
                 float yOffsetBottom = 0.0;
                 float stepWidth = 2.0 / steps;
                 if (shapeType == 1) {
                     float checkStepTop = floor(uvXTop * (steps * 0.5));
                     float checkStepBottom = floor(uvXBottom * (steps * 0.5));
                     float signOffsetTop = (mod(checkStepTop, 2.0) == 1.0) ? toothHeight : -toothHeight;
                     float signOffsetBottom = (mod(checkStepBottom, 2.0) == 1.0) ? toothHeight : -toothHeight;
                     yOffsetTop = signOffsetTop;
                     yOffsetBottom = isInterlocking ? signOffsetTop : -signOffsetBottom;
                 }
                 else if (shapeType == 2) {
                     float radiusX = stepWidth * 0.5;
                     float radiusY = toothHeight;
                     float localXTop = mod(uvXTop, stepWidth);
                     float localXBottom = isInterlocking ? mod(uvXBottom + (stepWidth * 0.5), stepWidth) : mod(uvXBottom, stepWidth);
                     float dxTop = localXTop - radiusX;
                     float dxBottom = localXBottom - radiusX;
                     float dyTop = uv.y - topBoundary;
                     float dyBottom = uv.y - bottomBoundary;
                     float distTop = (dxTop * dxTop) / (radiusX * radiusX) + (dyTop * dyTop) / (radiusY * radiusY);
                     float distBottom = (dxBottom * dxBottom) / (radiusX * radiusX) + (dyBottom * dyBottom) / (radiusY * radiusY);
                     if (uv.y > topBoundary || distTop < 1.0) {
                         isJaw = true;
                     }
                     if (uv.y < bottomBoundary || distBottom < 1.0) {
                         isJaw = true;
                     }
                 }
                 else if (shapeType == 3) {
                     float triWaveTop = abs(fract(uvXTop * (steps * 0.5)) - 0.5) * 2.0;
                     float triWaveBottom = abs(fract(uvXBottom * (steps * 0.5)) - 0.5) * 2.0;
                     yOffsetTop = (triWaveTop - 0.5) * toothHeight * 2.0;
                     float yOffsetBotCalc = (triWaveBottom - 0.5) * toothHeight * 2.0;
                     yOffsetBottom = isInterlocking ? yOffsetTop : -yOffsetBotCalc;
                 }
                 else if (shapeType == 4) {
                     float triWaveTop = abs(fract(uvXTop * (steps * 0.5)) - 0.5) * 2.0;
                     float triWaveBottom = abs(fract(uvXBottom * (steps * 0.5)) - 0.5) * 2.0;
                     float trapezoidWaveTop = clamp((triWaveTop - 0.25) / 0.5, 0.0, 1.0);
                     float trapezoidWaveBottom = clamp((triWaveBottom - 0.25) / 0.5, 0.0, 1.0);
                     yOffsetTop = (trapezoidWaveTop - 0.5) * toothHeight * 2.0;
                     float yOffsetBotCalc = (trapezoidWaveBottom - 0.5) * toothHeight * 2.0;
                     yOffsetBottom = isInterlocking ? yOffsetTop : -yOffsetBotCalc;
                 }
                 else if (shapeType == 5) {
                     float rawWaveTop = fract(uvXTop * (steps * 0.5));
                     float sharpToothTop = max(0.0, 0.25 - abs(rawWaveTop - 0.25)) * 4.0;
                     yOffsetTop = toothHeight - (sharpToothTop * toothHeight);
                     if (isInterlocking) {
                         float rawWaveBottom = fract((uvXBottom + (0.5 / (steps * 0.5))) * (steps * 0.5));
                         float sharpToothBottom = max(0.0, 0.25 - abs(rawWaveBottom - 0.25)) * 4.0;
                         yOffsetBottom = -(toothHeight - (sharpToothBottom * toothHeight));
                     } else {
                         float rawWaveBottom = fract(uvXBottom * (steps * 0.5));
                         float sharpToothBottom = max(0.0, 0.25 - abs(rawWaveBottom - 0.25)) * 4.0;
                         yOffsetBottom = -(toothHeight - (sharpToothBottom * toothHeight));
                     }
                 }
                 else if (shapeType == 6) {
                     float waveTop = sin(uvXTop * steps * 3.14159265);
                     float waveBottom = sin(uvXBottom * steps * 3.14159265);
                     yOffsetTop = waveTop * toothHeight;
                     yOffsetBottom = isInterlocking ? yOffsetTop : -waveBottom * toothHeight;
                 }
                 if (shapeType == 1 || shapeType == 3 || shapeType == 4 || shapeType == 5 || shapeType == 6) {
                     if (uv.y > (topBoundary + yOffsetTop) || uv.y < (bottomBoundary + yOffsetBottom)) {
                         isJaw = true;
                     }
                 }
             }
             fragColor = isJaw ? jawColor : baseColor;
         float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) { resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          else if( int(amzp_blendMode)==3 ) { factor *= amzp_hardness; resultfinal = (newLayer(texColor, factor) * amzp_hardness) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha) * texColor.a;
    }

